output_text:
[
  {
    "id": "no_carts_in_single_file_shelf_aisles",
    "text": "Shopping carts must not be taken into single-file shelf corridors.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_before_central_customer_aisle",
    "text": "On arriving with a cart at the central narrow-aisle mouth, the shopper must park the cart before continuing.",
    "abstraction": {
      "state_properties": {
        "centralAisleMouth": "at(6,3)"
      },
      "events": {
        "enterCentralBayWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "centralAisleMouth"
        },
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterCentralBayWithCart",
      "discharge": "cartDrop"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "A shopper who parks a cart must retrieve it before leaving the store.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartPickup": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDrop",
      "discharge": "cartPickup"
    }
  },
  {
    "id": "park_only_at_narrow_aisle_mouths",
    "text": "Carts may only be parked at designated mouths of narrow customer-only aisles.",
    "abstraction": {
      "state_properties": {
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartDrop": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartDrop",
          {
            "not": "narrowAisleMouth"
          }
        ]
      }
    }
  },
  {
    "id": "no_horizontal_walking_away_from_cart",
    "text": "After leaving the cart behind, shoppers should not walk horizontally through the shopping area.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "awayFromEntranceWithoutCart": {
          "and": [
            {
              "not": "hasCart"
            },
            {
              "not": "entranceOrCartBay"
            }
          ]
        },
        "horizontalMove": {
          "or": [
            "E",
            "W"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "awayFromEntranceWithoutCart",
          "horizontalMove"
        ]
      }
    }
  },
  {
    "id": "no_cartless_wandering_outside_customer_aisles",
    "text": "A shopper without a cart may only be at the entrance/cart bay, a cart-parking mouth, or a single-file customer aisle.",
    "abstraction": {
      "state_properties": {
        "entranceOrCartBay": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "narrowAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "adjShelf",
            "shelfE",
            "shelfW"
          ]
        },
        "allowedNoCartArea": {
          "or": [
            "entranceOrCartBay",
            "narrowAisleMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedNoCartArea"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_interaction_from_west_side_of_shelf",
    "text": "A shopper pushing a cart should not take items from a shelf that is immediately to their east.",
    "abstraction": {
      "state_properties": {
        "shelfImmediatelyEast": "shelfE"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "shelfImmediatelyEast"
        ]
      }
    }
  },
  {
    "id": "cart_traffic_one_way_no_west",
    "text": "Cart traffic is one-way: shoppers pushing carts must not move west.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "W"
        ]
      }
    }
  }
]
